import pyAether as pyScript
def use_MdePlatSession_close():
    def close_session(mde):
        """Close an MdePlatSession if valid, handling errors."""
        if mde is None:
            print("No session to close.")
            return
        if not mde.isValid():
            print("Session is not valid.")
            return
        if mde.close():
            print("Session closed successfully.")
        else:
            error = mde.getLastError()
            print(f"Failed to close session: {error}")
    # Example usage
    if __name__ == "__main__":
        try:
            mde = pyScript.MdePlatSession.open("testLib", "testCell", "platform")
            if mde is not None:
                close_session(mde)
        except Exception as e:
            print(f"Error opening or closing session: {e}")
        finally:
            # Ensure any open session is closed
            if 'mde' in locals() and mde is not None and mde.isValid():
                mde.close()

