import pyAether
def use_MdePlatSession_getLibName():
    def get_lib_name(lib, cell, view):
        mde = pyAether.MdePlatSession.open(lib, cell, view)
        if mde is None:
            error = pyAether.MdePlatSession.staticLastError()
            print(f"Failed to open session: {error}")
            return None
        try:
            if mde.isValid():
                lib_name = mde.getLibName()
                print(f"Working on: {lib_name}")
                return lib_name
            else:
                print("Session is not valid")
                return None
        finally:
            if mde:
                mde.close()
    if __name__ == "__main__":
        # Example usage
        lib_name = get_lib_name("testLib", "testCell", "platform")
        print(f"Result: {lib_name}")

